/* c01 reading pilot. All teaching text comes from the author's frozen readingLessons. */
const textbookPilotLessonIds=Object.freeze(['c01-read-flow','c01-read-loop','c01-read-observation','c01-read-stop']);
function textbookIsPilot(book){return book?.version==='textbook-draft-0.6-pilot';}
function textbookPilotComplete(chapter){return Boolean(chapter?.readingIntro&&['problem','learningOutcome','prerequisiteSummary','caseSummary'].every(k=>typeof chapter.readingIntro[k]==='string'&&chapter.readingIntro[k].trim())&&Array.isArray(chapter.readingLessons)&&chapter.readingLessons.length===4&&textbookPilotLessonIds.every((id,i)=>{const lesson=chapter.readingLessons[i];return lesson?.id===id&&lesson.order===i+1&&['title','coreQuestion','learningAction','bodyMarkdown','checkQuestion','checkAnswer'].every(k=>typeof lesson[k]==='string'&&lesson[k].trim());}));}
function textbookComparisonHTML(book){const original=book?.version==='textbook-draft-0.5';return '<div class="action-row textbook-comparison" aria-label="示范与原稿对照"><button class="'+(original?'outline':'primary')+'" data-textbook-chapter="c01" data-textbook-source="current" aria-pressed="'+(!original)+'">新版示范</button><button class="'+(original?'primary':'outline')+'" data-textbook-chapter="c01" data-textbook-source="v05" aria-pressed="'+original+'">查看 v0.5 原稿</button></div>';}
function textbookPilotEvidenceHTML(book,chapter){const sources=textbookList(book.sources).filter(s=>textbookList(chapter.sourceIds).includes(s.id));return '<details class="textbook-pilot-evidence"><summary>来源与验证说明</summary><section><h3>学习目标与教案</h3><h4>原模块目标</h4>'+textbookValues(chapter.objectives)+'<h4>先修</h4>'+textbookValues(chapter.prerequisites)+'<h4>目标去向</h4>'+textbookValues(chapter.objectiveCoverage||chapter.objectiveMapping||chapter.objectiveRouting||book.objectiveDisposition||chapter.readingLessons.map(l=>({title:l.title,learningAction:l.learningAction,objectiveIds:l.objectiveIds,knowledgePointIds:l.knowledgePointIds})))+'<details><summary>九节完整教案</summary>'+chapter.sections.map((s,i)=>'<section class="textbook-section" id="textbook-'+textbookEscape(chapter.id)+'-'+textbookEscape(s.id)+'"><h4>'+String(i+1).padStart(2,'0')+' · '+textbookEscape(s.title)+'</h4>'+textbookMarkdown(s.bodyMarkdown,3)+'<p class="note">本节资料：'+textbookEscape(textbookList(s.sourceIds).join('、')||'原创教学设计')+'</p></section>').join('')+'</details><details><summary>原知识点、情景题与参考解析</summary>'+textbookList(chapter.knowledgePoints).map(textbookKnowledgeHTML).join('')+'</details><details><summary>原三层任务与参考解法</summary>'+textbookList(chapter.exercises).map(textbookExerciseHTML).join('')+'</details><details><summary>既有量规（尚未行业校准）</summary>'+textbookValues(book.rubric)+'</details></section><section><h3>参考来源</h3>'+sources.map(textbookSourceHTML).join('')+'<details><summary>具体论断与适用范围</summary>'+textbookList(chapter.claims).map(c=>'<article class="textbook-claim"><h4>'+textbookEscape(c.id)+'</h4><p>'+textbookEscape(c.text)+'</p><p>'+textbookEscape(textbookStatus(c.status))+' · 来源：'+textbookEscape(textbookList(c.sourceIds).join('、')||'原创设计')+'</p>'+textbookValues(c.locators||[])+textbookValues(c.limits)+'</article>').join('')+'</details></section><section><h3>示例验证</h3>'+textbookList(chapter.examples).map(e=>'<article class="textbook-example"><h4>'+textbookEscape(e.title||e.id)+'</h4><p>'+textbookEscape(textbookStatus(e.kind))+' · '+textbookEscape(textbookStatus(e.executionStatus||'not_run'))+'</p><h5>环境</h5>'+textbookValues(e.environment)+'<h5>预期结果</h5>'+textbookValues(e.expectedResult)+'<h5>实际结果与证据</h5>'+textbookValues(e.actualResults||[])+textbookValues(e.evidenceReferences||[])+'<h5>限制</h5>'+textbookValues(e.limits)+'</article>').join('')+'<details><summary>作者验证规格（不是实测）</summary>'+textbookValues(chapter.verification||'未提供')+'</details></section><section><h3>独立审校</h3>'+textbookReviewHTML(book,'c01')+'</section><section><h3>版本与追踪</h3><p>本轮仅改写 c01；其他十一章保留 v0.5。当前阅读包：'+textbookEscape(book.version)+'；当前章：'+textbookEscape(chapter.version||book.version)+'</p><p>源包 SHA256（打包记录）：'+textbookEscape(textbookMetaFor(book)?.sourceSha256||'未提供')+'</p><h4>本章具体案例</h4>'+textbookValues(chapter.chapterCase)+'<h4>作者过程与限制</h4>'+textbookValues(book.provenance)+textbookValues(chapter.review)+textbookValues(chapter.limits||[])+textbookValues(book.limitations||[])+'<details><summary>保留的工程项目框架与术语</summary>'+textbookValues(book.mainProject)+textbookValues(book.glossary)+'</details><div class="action-row"><button class="outline" data-textbook-chapter="c01" data-textbook-source="v05">阅读 v0.5 完整 c01</button><button class="outline" data-textbook-download="c01" data-textbook-download-source="v05">下载 v0.5 原 c01</button><button class="outline" data-view="product-review">当前产品达标复盘与历史报告</button></div></section></details>';}
function textbookPilotChapterHTML(book,chapter){const intro=chapter.readingIntro;return '<article class="card lesson textbook-chapter textbook-pilot-chapter" id="textbook-chapter-c01"><h2 id="textbook-title-c01">'+textbookEscape(chapter.readingTitle||chapter.title)+'</h2><p class="textbook-pilot-problem">'+textbookEscape(intro.problem)+'</p><p class="textbook-pilot-status">AI教材草稿。人类行业专家审核和真实学习效果待完成。</p><dl class="textbook-pilot-intro"><dt>这次要学会什么</dt><dd>'+textbookEscape(intro.learningOutcome)+'</dd><dt>需要哪些前置知识</dt><dd>'+textbookEscape(intro.prerequisiteSummary)+'</dd><dt>贯穿案例</dt><dd>'+textbookEscape(intro.caseSummary)+'</dd></dl><div class="textbook-lesson-nav" aria-label="本章小课">'+chapter.readingLessons.map((l,i)=>'<a href="#textbook-lesson-'+textbookEscape(l.id)+'" data-textbook-anchor="textbook-lesson-'+textbookEscape(l.id)+'">'+(i+1)+' · '+textbookEscape(l.title)+'</a>').join('')+'</div>'+chapter.readingLessons.map((l,i)=>'<section class="textbook-pilot-lesson" id="textbook-lesson-'+textbookEscape(l.id)+'"><h3>'+String(i+1).padStart(2,'0')+' · '+textbookEscape(l.title)+'</h3><p class="textbook-lesson-question">'+textbookEscape(l.coreQuestion)+'</p>'+textbookMarkdown(l.bodyMarkdown,3)+'<div class="textbook-quick-check"><h4>小练习</h4>'+textbookMarkdown(l.checkQuestion,3)+'<details><summary>查看参考解析</summary>'+textbookMarkdown(l.checkAnswer,3)+'<p class="note">这是公开参考解析，不是保留测评或学员作品。</p></details></div></section>').join('')+textbookPilotEvidenceHTML(book,chapter)+'</article>';}
function textbookPilotPageHTML(book,chapter,nav,pager,legacy){const desktop=typeof window!=='undefined'&&typeof window.matchMedia==='function'&&window.matchMedia('(min-width:901px)').matches;const directory='<details class="textbook-pilot-directory" '+(desktop?'open':'')+'><summary>教材目录 · 当前：'+textbookEscape(chapter.readingTitle||chapter.title)+'</summary>'+nav+'</details>';return '<div class="page-title"><div><span class="eyebrow">AGENT READING PILOT</span><h1>Agent 架构示范</h1><p>本轮只改写 c01，其他十一章仍为 v0.5。是否更易理解，等待你的实际阅读反馈。</p></div></div>'+textbookComparisonHTML(book)+'<div class="textbook-pilot-tools"><button class="outline" data-textbook-download="c01">下载当前示范章</button><details><summary>教材工具与原稿</summary><div class="action-row"><button class="outline" data-textbook-download="all">下载混合版本全书</button><button class="outline" data-textbook-chapter="all" data-textbook-source="v05">阅读 v0.5 全书</button><button class="outline" data-textbook-download="all" data-textbook-download-source="v05">下载 v0.5 全书</button>'+legacy+'<button class="outline" data-view="curriculum">课程地图</button><button class="outline" data-view="projects">项目与原练习</button><button class="outline" data-view="reflections">历史学习复盘</button><button class="outline" data-view="product-review">当前产品达标复盘</button></div></details></div><div class="book-layout textbook-layout textbook-pilot-layout">'+directory+'<div class="textbook-body">'+textbookPilotChapterHTML(book,chapter)+pager+'</div></div>';}
